head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거)
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
scwin.grid1_ongroupby = function(options) {
	options.groupbyHeader = [{
		colSpan: "3",
		inputType: "expression",
		expression: " toggle() + depthStr() + ' [ ' +',' + count() + ' 건 ] ' ",
		align: "left"
	}];
	options.groupbyFooter = [{
		targetIndex: 0,
		colSpan: "3",
		inputType: "expression",
		expression: " SUM('col3')",
		align: "center"
	}];
	options.hideFooter = true;
	this.groupby(options);
	return true;
};
scwin.trigger1_onclick = function() {
	scwin.data1 = [
		"0", "A", 1,
		"0", "A", 2,
		"0", "A", 3,
		"0", "B", 4,
		"0", "B", 5,
		"0", "B", 6,
		"1", "B", 7,
		"1", "C", 8,
		"1", "C", 9,
		"1", "C", 10,
		"1", "C", 11
	];
	dataList1.setData(scwin.data1.slice(0));
};
scwin.checkVal = function() {
	return scwin.__getDom($p.id+"grid1_cell_0_0").firstElementChild.innerText.trim() == '0 [ ,6 건 ]';
};
